"""Generate the displayed smoke table only from per-image machine results."""
import json
from pathlib import Path
from tp.eval.aggregate import aggregate
from tp.provenance import ROOT,write_json,sha256

RUNS={
    "raw_prompt":"mirror3d_raw_prompt_smoke_v2",
    "UniDepthV2-S":"mirror3d_unidepth_smoke_v1",
    "RobustAlign global":"mirror3d_robust_global_smoke_v1",
    "RobustAlign local":"mirror3d_robust_local_smoke_v2",
}


def main():
    lines=["# Five-scene real training smoke", "",
           "Generated by `python -m scripts.summarize_smoke` from per-image JSON. No test-set claims, no scale alignment.","",
           "NYU registered axial-Z convention; strict RGB-axis Z is unqualified. Background GT is inpainted. Equal image means within scenes, then equal scene means.","",
           "| Method | C AbsRel | Clean AbsRel | All AbsRel | IR | DOR | Invalid pixels |",
           "|---|---:|---:|---:|---:|---:|---:|"]
    output={}
    for name,run in RUNS.items():
        p=ROOT/"results"/run/"per_image.json"
        metrics=aggregate(json.loads(p.read_text()))["datasets"]["mirror3d_nyu"]["metrics"]
        vals=[metrics["regions"][r]["absrel"] for r in ("C","clean","all")]
        vals += [metrics[k]["value"] for k in ("IR","DOR")]
        invalid=metrics["regions"]["all"]["invalid_count"]
        fmt=lambda v:"NA" if v is None else f"{v:.6f}"
        lines.append("| "+name+" | "+" | ".join(map(fmt,vals))+f" | {invalid} |")
        output[name]=dict(run=run,per_image_sha256=sha256(p),metrics=metrics)
    lines += ["", "Local alignment produced 1,454 invalid predictions in playroom_0007/frame440. Its affected continuous metrics are NA, with no pixel or scene dropped. This failure is retained for method development.","",
              "Global alignment reduces C error in this diagnostic while increasing clean-region error relative to raw_prompt. Five selected training scenes do not establish generalization or formal significance.","",
              "Paired 10,000-resample descriptive intervals: `results/mirror3d_paired_comparison_v2/paired_bootstrap.json`. Empty/invalid scene comparisons stay NA. No cross-dataset Holm result is claimed because only one dataset was evaluated.","",
              "Separate precise-mirror references and scene tables are in each run's `per_image_mirror_only.json` / `summary_mirror_only.json` / `summary.json`.",""]
    (ROOT/"docs/smoke_results.md").write_text("\n".join(lines),encoding="utf-8")
    write_json(ROOT/"docs/smoke_results.json",dict(stage="real_train_engineering_smoke_only",source="per_image.json",methods=output))


if __name__=="__main__":main()
